INSERT INTO quality_scenario_seed VALUES ($quality$[{"practice_id": "access-review-exception-handling", "slug": "access_review_exception_handling", "title": "Access-review exception handling", "brief": "Investigate, contain, and close access-review exceptions without erasing the audit trail.", "track": "launch-curriculum", "frameworks": ["iso27001", "soc2"], "difficulty": "practitioner", "entry_stage_id": "triage", "stages": [{"id": "triage", "sequence": 1, "agent_message": "A quarterly review finds a departed contractor still in a privileged group. The account is disabled but its API token remains valid.", "demands": ["Triage the exception and immediate exposure", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "triage_correct", "label": "Revoke the token, preserve logs, identify last use, and open an incident assessment", "consequence": "The decision remains evidenced, bounded, and owned. The selected action “Revoke the token, preserve logs, identify last use, and open an incident assessment” changes ownership, retained evidence, and residual risk at triage.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.18, a.8.15 proportionately.", "next_stage": "ownership", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.18", "a.8.15"], "display_order": 1, "authored_risk_outcome": "controlled", "remediation": "Reperform triage the exception and immediate exposure using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "triage_qualified", "label": "Suspend the token and preserve logs while incident severity is confirmed immediately", "consequence": "Immediate exposure is limited, but a time-bound condition remains open. The selected action “Suspend the token and preserve logs while incident severity is confirm