nt of Applicability exclusion review to retained evidence and residual risk.", "demands": ["Synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "State the limitation that would prevent closure"], "terminal": false, "choices": [{"id": "synthesis_4_controlled", "label": "Document and execute the evidenced response for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "consequence": "The decision to “Document and execute the evidenced response for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes the evidence trail, accountable owner, and residual risk for this specific synthesis 4 decision. The selected action “Document and execute the evidenced response for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes ownership, retained evidence, and residual risk at synthesis_4.", "is_correct": true, "rationale": "This controlled response is assessed against a.5.1, a.5.19, a.5.2 and the requirement for attributable evidence, bounded authority, and a dated next action.", "next_stage": "complete", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.1", "a.5.19", "a.5.2"], "display_order": 1, "remediation": "Reperform synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion using a named owner, attributable evidence, a decision deadline, and an effectiveness check.", "authored_risk_outcome": "controlled"}, {"id": "synthesis_4_qualified_alternative", "label": "Contain the immediate issue and time-box the remaining work for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "consequence": "The decision to “Contain the immediate issue and time-box the remaining work for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes the evidence trail, accountable owner, and residual risk for this specific synthesis 4 decision. The selected action “Contain the immediate issue and time-box the remaining work for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes ownership, retained evidence, and residual risk at synthesis_4.", "is_correct": false, "rationale": "This qualified alternative response is assessed against a.5.1, a.5.19, a.5.2 and the requirement for attributable evidence, bounded authority, and a dated next action.", "next_stage": "complete", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 5, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.1", "a.5.19", "a.5.2"], "display_order": 2, "remediation": "Reperform synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion using a named owner, attributable evidence, a decision deadline, and an effectiveness check.", "authored_risk_outcome": "qualified_alternative"}, {"id": "synthesis_4_control_failure", "label": "Accept the current position without independently testing synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "consequence": "The decision to “Accept the current position without independently testing synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes the evidence trail, accountable owner, and residual risk for this specific synthesis 4 decision. The selected action “Accept the current position without independently testing synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes ownership, retained evidence, and residual risk at synthesis_4.", "is_correct": false, "rationale": "This control failure response is assessed against a.5.1, a.5.19, a.5.2 and the requirement for attributable evidence, bounded authority, and a dated next action.", "next_stage": "complete", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -12, "escalation": -12, "remediation": -12}, "control_refs": ["a.5.1", "a.5.19", "a.5.2"], "display_order": 3, "remediation": "Reperform synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion using a named owner, attributable evidence, a decision deadline, and an effectiveness check.", "authored_risk_outcome": "control_failure"}, {"id": "synthesis_4_unmanaged_delay", "label": "Wait for another team before assigning ownership for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "consequence": "The decision to “Wait for another team before assigning ownership for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes the evidence trail, accountable owner, and residual risk for this specific synthesis 4 decision. The selected action “Wait for another team before assigning ownership for synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion” changes ownership, retained evidence, and residual risk at synthesis_4.", "is_correct": false, "rationale": "This unmanaged delay response is assessed against a.5.1, a.5.19, a.5.2 and the requirement for attributable evidence, bounded authority, and a dated next action.", "next_stage": "complete", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -8, "remediation": -8}, "control_refs": ["a.5.1", "a.5.19", "a.5.2"], "display_order": 4, "remediation": "Reperform synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion using a named owner, attributable evidence, a decision deadline, and an effectiveness check.", "authored_risk_outcome": "unmanaged_delay"}], "objective_id": "objective_3", "objective": "Keep, rewrite, reverse, or investigate an exclusion", "evidence_task": {"prompt": "Synthesise the evidence and justify closure for keep, rewrite, reverse, or investigate an exclusion", "required_attributes": ["source", "owner", "operating_period", "authenticity", "completeness"]}}, {"id": "complete", "sequence": 5, "agent_message": "", "demands": [], "terminal": true, "choices": []}], "source_version": "1", "quality": {"standard_version": "practice-quality-v1", "objectives_assessed": ["Test exclusions against organizational facts", "Reject outsourcing as automatic exclusion", "Keep, rewrite, reverse, or investigate an exclusion"], "target_dimensions": ["control_mapping", "evidence", "escalation", "remediation"], "reviewed_by": "Astra Curriculum Review Board", "reviewed_at": "2026-10-25T14:00:00Z"}, "content_hash": "665af53493306b103e91b4be4e996ea4957fa4893d6d78c92c956d131671e865"}, {"practice_id": "supplier-due-diligence", "slug": "supplier_due_diligence", "title": "Supplier due diligence", "brief": "Evaluate a critical supplier using scoped evidence, risk ownership, and contract-ready conditions.", "track": "launch-curriculum", "frameworks": ["iso27001", "dora"], "difficulty": "practitioner", "entry_stage_id": "scope", "stages": [{"id": "scope", "sequence": 1, "agent_message": "A payroll provider sent a generic security questionnaire. Procurement wants approval before the data-flow workshop.", "demands": ["Scope diligence to the actual service", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "scope_correct", "label": "Map data, access, subcontractors, criticality, and jurisdictions before deciding evidence needs", "consequence": "The decision remains evidenced, bounded, and owned. The selected action “Map data, access, subcontractors, criticality, and jurisdictions before deciding evidence needs” changes ownership, retained evidence, and residual risk at scope.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.19, a.5.21 proportionately.", "next_stage": "assurance", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.19", "a.5.21"], "display_order": 1, "authored_risk_outcome": "controlled", "remediation": "Reperform scope diligence to the actual service using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "scope_qualified", "label": "Permit commercial discussion while blocking data transfer until service scope and evidence needs are confirmed", "consequence": "Immediate exposure is limited, but a time-bound condition remains open. The selected action “Permit commercial discussion while blocking data transfer until service scope and evidence needs are confirmed” changes ownership, retained evidence, and residual risk at scope.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.19, a.5.21.", "next_stage": "assurance", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 5, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.19", "a.5.21"], "display_order": 2, "authored_risk_outcome": "qualified_alternative", "remediation": "Reperform scope diligence to the actual service using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "scope_failure", "label": "Approve based on the completed generic questionnaire", "consequence": "The control conclusion is unsupported and risk increases. The selected action “Approve based on the completed generic questionnaire” changes ownership, retained evidence, and residual risk at scope.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.19, a.5.21.", "next_stage": "complete", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -12, "escalation": -12, "remediation": -12}, "control_refs": ["a.5.19", "a.5.21"], "display_order": 3, "authored_risk_outcome": "control_failure", "remediation": "Reperform scope diligence to the actual service using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "scope_defer", "label": "Use the provider's marketing security page as scope evidence", "consequence": "The decision clock continues without accountable action. The selected action “Use the provider's marketing security page as scope evidence” changes ownership, retained evidence, and residual risk at scope.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.19, a.5.21.", "next_stage": "complete", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -8, "remediation": -8}, "control_refs": ["a.5.19", "a.5.21"], "display_order": 4, "authored_risk_outcome": "unmanaged_delay", "remediation": "Reperform scope diligence to the actual service using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}], "objective_id": "objective_1", "objective": "Scope diligence to the service and data flow", "evidence_task": {"prompt": "Scope diligence to the actual service", "required_attributes": ["source", "owner", "operating_period", "authenticity", "completeness"]}}, {"id": "assurance", "sequence": 2, "agent_message": "The supplier provides a clean assurance report, but its scope excludes the subcontractor hosting backups.", "demands": ["Evaluate assurance boundaries", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "assurance_correct", "label": "Record the exclusion, obtain relevant subcontractor assurance or compensating evidence, and reassess residual risk", "consequence": "The decision remains evidenced, bounded, and owned. The selected action “Record the exclusion, obtain relevant subcontractor assurance or compensating evidence, and reassess residual risk” changes ownership, retained evidence, and residual risk at assurance.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.19, a.5.22 proportionately.", "next_stage": "conditions", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.19", "a.5.22"], "display_order": 1, "authored_risk_outcome": "controlled", "remediation": "Reperform evaluate assurance boundaries using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "assurance_qualified", "label": "Accept the report provisionally with a time-bound condition for backup-host evidence", "consequence": "Immediate exposure is limited, but a time-bound condition remains open. The selected action “Accept the report provisionally with a time-bound condition for backup-host evidence” changes ownership, retained evidence, and residual risk at assurance.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.19, a.5.22.", "next_stage": "conditions", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 5, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.19", "a.5.22"], "display_order": 2, "authored_risk_outcome": "qualified_alternative", "remediation": "Reperform evaluate assurance boundaries using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "assurance_failure", "label": "Treat the clean opinion as covering every subcontractor", "consequence": "The control conclusion is unsupported and risk increases. The selected action “Treat the clean opinion as covering every subcontractor” changes ownership, retained evidence, and residual risk at assurance.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.19, a.5.22.", "next_stage": "conditions", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -12, "escalation": -12, "remediation": -12}, "control_refs": ["a.5.19", "a.5.22"], "display_order": 3, "authored_risk_outcome": "control_failure", "remediation": "Reperform evaluate assurance boundaries using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "assurance_defer", "label": "Ignore backup hosting because it is indirect", "consequence": "The decision clock continues without accountable action. The selected action “Ignore backup hosting because it is indirect” changes ownership, retained evidence, and residual risk at assurance.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.19, a.5.22.", "next_stage": "conditions", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -8, "remediation": -8}, "control_refs": ["a.5.19", "a.5.22"], "display_order": 4, "authored_risk_outcome": "unmanaged_delay", "remediation": "Reperform evaluate assurance boundaries using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}], "objective_id": "objective_2", "objective": "Validate assurance boundaries and exceptions", "evidence_task": {"prompt": "Evaluate assurance boundaries", "required_attributes": ["source", "owner", "operating_period", "authenticity", "completeness"]}}, {"id": "conditions", "sequence": 3, "agent_message": "Launch is urgent and one medium residual risk remains around deletion verification.", "demands": ["Convert residual risk into governed conditions", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "conditions_correct", "label": "Assign an authorized risk owner, add deletion evidence and audit rights to the contract, and set monitoring dates", "consequence": "The decision remains evidenced, bounded, and owned. The selected action “Assign an authorized risk owner, add deletion evidence and audit rights to the contract, and set monitoring dates” changes ownership, retained evidence, and residual risk at conditions.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.20, a.5.22 proportionately.", "next_stage": "complete", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.20", "a.5.22"], "display_order": 1, "authored_risk_outcome": "controlled", "remediation": "Reperform convert residual risk into governed conditions using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "conditions_qualified", "label": "Approve a limited pilot with no production personal data until deletion evidence is verified", "consequence": "Immediate exposure is limited, but a time-bound condition remains open. The selected action “Approve a limited pilot with no production personal data until deletion evidence is verified” changes ownership, retained evidence, and residual risk at conditions.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.20, a.5.22.", "next_stage": "complete", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 5, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.20", "a.5.22"], "display_order": 2, "authored_risk_outcome": "qualified_alternative", "remediation": "Reperform convert residual risk into governed conditions using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "conditions_failure", "label": "Accept the risk in procurement meeting notes", "consequence": "The control conclusion is unsupported and risk increases. The selected action “Accept the risk in procurement meeting notes” changes ownership, retained evidence, and residual risk at conditions.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.20, a.5.22.", "next_stage": "complete", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -12, "escalation": -12, "remediation": -12}, "control_refs": ["a.5.20", "a.5.22"], "display_order": 3, "authored_risk_outcome": "control_failure", "remediation": "Reperform convert residual risk into governed conditions using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "conditions_defer", "label": "Launch fully and negotiate controls at renewal", "consequence": "The decision clock continues without accountable action. The selected action “Launch fully and negotiate controls at renewal” changes ownership, retained evidence, and residual risk at conditions.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.20, a.5.22.", "next_stage": "complete", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -8, "remediation": -8}, "control_refs": ["a.5.20", "a.5.22"], "display_order": 4, "authored_risk_outcome": "unmanaged_delay", "remediation": "Reperform convert residual risk into governed conditions using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}], "objective_id": "objective_3", "objective": "Translate residual risk into contract and monitoring conditions", "evidence_task": {"prompt": "Convert residual risk into governed conditions", "required_attributes": ["source", "owner", "operating_period", "authenticity", "completeness"]}}, {"id": "complete", "sequence": 4, "agent_message": "", "demands": [], "terminal": true, "choices": []}], "source_version": "1", "quality": {"standard_version": "practice-quality-v1", "objectives_assessed": ["Scope diligence to the service and data flow", "Validate assurance boundaries and exceptions", "Translate residual risk into contract and monitoring conditions"], "target_dimensions": ["control_mapping", "evidence", "escalation", "remediation"], "reviewed_by": "Astra Curriculum Review Board", "reviewed_at": "2026-10-25T14:00:00Z"}, "content_hash": "43bf92fcdeeeaaa57d77f1eb95c5c9ee86c076d7979f752c4cf4706e2e23adca"}, {"practice_id": "supplier-incident-response", "slug": "supplier_incident_response", "title": "Third-Party Breach: Supplier Security Incident", "brief": "You are the Information Security Lead at AstraLabs Group. Your SaaS HR platform provider has just notified you of a security incident affecting customer data. You have 72 hours under GDPR Article 33 — but first you need to decide how to respond to the supplier and protect the organisation. Your decisions drive the investigation and notification path.", "track": "ai-risk-lead", "frameworks": ["iso27001-2022"], "difficulty": "practitioner", "entry_stage_id": "initial_assessment", "stages": [{"id": "initial_assessment", "sequence": 1, "agent_message": "We have sent you the incident report as contracted. The breach affected names, email addresses, and job titles for your employee records — approximately 340 people. We believe it was contained at 03:00 this morning but forensics are still running. We have patched the vector. What do you need from us right now?", "demands": ["Full forensic report within 24 hours", "Confirmation of data scope and affected records", "Evidence that the attack vector is closed", "Named incident coordinator on your side"], "terminal": false, "choices": [{"id": "contain_and_investigate", "label": "Contain first — demand evidence before any action", "consequence": "You hold all external communication until forensics confirm scope. Investigation is controlled but the GDPR clock is running with no notification started. The selected action “Contain first — demand evidence before any action” changes ownership, retained evidence, and residual risk at initial_assessment.", "is_correct": false, "rationale": "ISO 27001:2022 A.5.26 requires response to information security incidents — containment alone without parallel notification assessment fails the response objective. GDPR Article 33 runs independently of forensic completion.", "next_stage": "notification_decision", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 5, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.26"], "display_order": 1, "authored_risk_outcome": "delayed_response", "remediation": "Reperform full forensic report within 24 hours using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "invoke_supplier_contract", "label": "Invoke contract — enforce SLA and evidence obligations", "consequence": "You formally invoke the supplier's security obligations under the DPA and demand the forensic report, logs, and a named coordinator within the contracted SLA. Investigation and notification assessment run in parallel. The selected action “Invoke contract — enforce SLA and evidence obligations” changes ownership, retained evidence, and residual risk at initial_assessment.", "is_correct": true, "rationale": "Satisfies ISO 27001:2022 A.5.19 (information security in supplier relationships) and A.5.20 (addressing security within supplier agreements). Parallel tracks preserve the GDPR Article 33 window while enforcing contractual evidence obligations.", "next_stage": "notification_decision", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 12, "remediation": 12}, "control_refs": ["a.5.19", "a.5.20"], "display_order": 2, "authored_risk_outcome": "controlled", "remediation": "Reperform full forensic report within 24 hours using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "notify_authority_immediately", "label": "Notify supervisory authority immediately", "consequence": "You file a precautionary Article 33 notification before forensics complete. The authority is informed but the notification may need material amendment once scope is confirmed. The selected action “Notify supervisory authority immediately” changes ownership, retained evidence, and residual risk at initial_assessment.", "is_correct": false, "rationale": "ISO 27001:2022 A.6.8 requires reporting through proper channels with accurate information. A premature notification without confirmed scope risks a materially inaccurate filing — the obligation is to notify without undue delay once you know, not before.", "next_stage": "complete", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -12, "escalation": -12, "remediation": -12}, "control_refs": ["a.6.8"], "display_order": 3, "authored_risk_outcome": "premature_notification", "remediation": "Reperform full forensic report within 24 hours using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}, {"id": "escalate_to_dpo", "label": "Escalate to DPO — delegate the response decision", "consequence": "You route the incident to the DPO and stand down from the technical response. The DPO takes over notification assessment but the technical investigation loses its security lead. The selected action “Escalate to DPO — delegate the response decision” changes ownership, retained evidence, and residual risk at initial_assessment.", "is_correct": false, "rationale": "ISO 27001:2022 A.5.26 assigns incident response responsibility — the security lead does not transfer that responsibility by escalating. DPO involvement is required but does not substitute for the security response track.", "next_stage": "complete", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -8, "remediation": -8}, "control_refs": ["a.5.26"], "display_order": 4, "authored_risk_outcome": "delegated", "remediation": "Reperform full forensic report within 24 hours using a named owner, attributable evidence, a decision deadline, and an effectiveness check."}], "objective_id": "objective_1", "objective": "Invoke contractual incident duties", "evidence_task": {"prompt": "Full forensic report within 24 hours", "required_attributes": ["source", "owner", "operating_period", "authenticity", "completeness"]}}, {"id": "notification_decision", "sequence": 2, "agent_message": "Forensics are complete. Confirmed: 340 employee records, names and emails only, no financial data, no passwords. Exfiltration cannot be ruled out — the attacker had access for six hours. We have the logs. The patch is verified. You have about 48 hours left on your GDPR clock. What is your notification position?", "demands": ["A decision on supervisory authority notification", "A decision on individual data subject notification", "Your evidence preservation instruction", "Confirmation of your internal escalation path"], "terminal": false, "choices": [{"id": "notify_authority_and_subjects", "label": "Notify authority and affected individuals", "consequence": "You file the Article 33 notification to the supervisory authority and send Article 34 communications to the 340 affected employees. Full comp